SELECT Schedario1.ID, Schedario1.annocomp, Schedario1.presente, Schedario1.categoria2, Schedario1.SESSO, Schedario1.cognome, Schedario1.nome, Schedario1.alias, Schedario1.cittadinanza, Schedario1.[stato di nascita], Schedario1.[luogo di nascita], Schedario1.[data di nascita], Schedario1.provenienza, Schedario1.consegna, Schedario1.entrataacc, Schedario1.destinazione2, Schedario1.zugentr, Schedario1.zugusc, Schedario1.motentr, Schedario1.sistemazione
FROM Schedario1
GROUP BY Schedario1.ID, Schedario1.annocomp, Schedario1.presente, Schedario1.categoria2, Schedario1.SESSO, Schedario1.cognome, Schedario1.nome, Schedario1.alias, Schedario1.cittadinanza, Schedario1.[stato di nascita], Schedario1.[luogo di nascita], Schedario1.[data di nascita], Schedario1.provenienza, Schedario1.consegna, Schedario1.entrataacc, Schedario1.destinazione2, Schedario1.zugentr, Schedario1.zugusc, Schedario1.motentr, Schedario1.sistemazione
HAVING (((Schedario1.zugentr) Is Not Null) AND ((Schedario1.zugusc) Is Null));
